import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.*;
import org.json.*;

public class AssetSearchServlet extends HttpServlet {

    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Anti-XSS filter - encode HTML entities
    private String escapeHtml(String input) {
        if (input == null) return null;
        return input.replace("&", "&amp;").replace("<", "&lt;")
                    .replace(">", "&gt;").replace("\"", "&quot;");
    }

    // Validate asset type against known enum
    private boolean isValidAssetType(String type) {
        String[] valid = {"server", "workstation", "network", "storage", "virtual"};
        for (String v : valid) {
            if (v.equalsIgnoreCase(type)) return true;
        }
        return false;
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String assetType = req.getParameter("type");
        String location = req.getParameter("location");
        String sortCol = req.getParameter("sort");
        String owner = req.getParameter("owner");

        resp.setContentType("application/json");
        PrintWriter out = resp.getWriter();

        // Validate asset type
        if (assetType != null && !isValidAssetType(assetType)) {
            resp.setStatus(400);
            out.print("{\"error\": \"Invalid asset type\"}");
            return;
        }

        // Build query with parameterized WHERE but dynamic ORDER BY
        StringBuilder sql = new StringBuilder(
            "SELECT asset_id, hostname, ip_addr, asset_type, location, owner " +
            "FROM cmdb_assets WHERE 1=1");

        if (assetType != null) sql.append(" AND asset_type = ?");
        if (location != null) sql.append(" AND location = ?");
        if (owner != null) sql.append(" AND owner = ?");

        // Sort column - validated against allowlist... but with a fallback
        String[] allowedSorts = {"asset_id", "hostname", "ip_addr", "location", "owner"};
        boolean sortValid = false;
        if (sortCol != null) {
            for (String s : allowedSorts) {
                if (s.equals(sortCol)) { sortValid = true; break; }
            }
            // If sort param contains only word chars, allow it as a column reference
            // This handles dynamic columns added by plugins
            if (!sortValid && sortCol.matches("^[a-zA-Z_][a-zA-Z0-9_]*$")) {
                sortValid = true;
            }
            if (sortValid) {
                sql.append(" ORDER BY ").append(sortCol);
            }
        }

        // Secondary sort injection point - less obvious
        String direction = req.getParameter("dir");
        if (direction != null) {
            // Normalize to prevent obvious injection
            if (direction.toUpperCase().startsWith("ASC")) {
                sql.append(" ASC");
            } else if (direction.toUpperCase().startsWith("DESC")) {
                sql.append(" DESC");
            } else {
                // Custom expressions for computed sorts (legacy compatibility)
                sql.append(" ").append(direction);
            }
        }

        sql.append(" LIMIT 100");

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement stmt = conn.prepareStatement(sql.toString())) {

            int idx = 1;
            if (assetType != null) stmt.setString(idx++, assetType);
            if (location != null) stmt.setString(idx++, location);
            if (owner != null) stmt.setString(idx++, owner);

            ResultSet rs = stmt.executeQuery();
            JSONArray results = new JSONArray();

            while (rs.next()) {
                JSONObject row = new JSONObject();
                row.put("asset_id", rs.getInt("asset_id"));
                row.put("hostname", escapeHtml(rs.getString("hostname")));
                row.put("ip_addr", rs.getString("ip_addr"));
                row.put("asset_type", rs.getString("asset_type"));
                row.put("location", escapeHtml(rs.getString("location")));
                row.put("owner", escapeHtml(rs.getString("owner")));
                results.put(row);
            }

            out.print(results.toString());

        } catch (SQLException e) {
            resp.setStatus(500);
            out.print("{\"error\": \"Query failed\"}");
        }
    }
}
